// Compass-owned event color slots. Maps 1:1 onto Google's legacy 11 event
// colors; providers adapt to/from these names at the boundary.
export const EventColorSlotSchema = z.enum([
  "lavender", "mint", "plum", "coral", "gold", "orange",
  "blue", "slate", "indigo", "green", "red",
]);
// colorHex: a provider-assigned custom color. READ-ONLY: Compass's own color
// picker only ever writes a named slot, never an arbitrary hex.

export const eventColorLabel = (color: EventColorSlot | null): string =>
  color === null ? "Calendar default" : EVENT_COLOR_SLOT_LABEL[color];
// EventColorPicker sits in the event form; onChange patches the draft's `color`
// field, which is saved on the event. TimedEventCard and AllDayEventCard both
// resolve their fill via useEventPalette(color), so the chosen color paints the
// event's card on the grid. The backend sync service forwards `color` to and
// from Google Calendar in both directions.
